select tablename, policyname, cmd, roles from pg_policies where schemaname = 'public' and tablename in ('team_members', 'team_member_positions') order by tablename, policyname;
select tablename, policyname, cmd from pg_policies where schemaname = 'public' and cmd <> 'SELECT' and (qual ilike '%is_team_leader%' or with_check ilike '%is_team_leader%' or qual ilike '%is_any_team_leader%' or with_check ilike '%is_any_team_leader%');
do $$ declare l record; a record; otra uuid; pos uuid; n int; ra text; rb text; rc text; rd text; re text; begin select tm.id as tm_id, tm.team_id, tm.organization_id, m.email into l from public.team_members tm join public.members m on m.id = tm.member_id where tm.is_leader and m.email is not null and not exists (select 1 from public.organization_members om where om.person_id = tm.member_id and om.role in ('owner', 'admin')) limit 1; if l.tm_id is null then raise exception 'No hay un líder que no sea administrador para probar'; end if; select m.email into a from public.organization_members om join public.members m on m.id = om.person_id where om.role in ('owner', 'admin') and om.organization_id = l.organization_id and m.email is not null limit 1; if a.email is null then raise exception 'No hay un administrador para probar'; end if; select m.id into otra from public.members m where m.organization_id = l.organization_id and not exists (select 1 from public.team_members x where x.member_id = m.id and x.team_id = l.team_id) limit 1; select p.id into pos from public.team_positions p where p.team_id = l.team_id and p.archived_at is null limit 1; if otra is null or pos is null then raise exception 'Falta una persona fuera del equipo o una posición del equipo para probar'; end if; set local role authenticated; perform set_config('request.jwt.claims', json_build_object('email', l.email, 'role', 'authenticated')::text, true); update public.team_members set is_leader = false where id = l.tm_id; get diagnostics n = row_count; ra := case when n = 0 then 'OK: no pudo cambiar is_leader' else 'FALLO: cambió is_leader en ' || n || ' fila' end; begin insert into public.team_members (member_id, team_id, organization_id, is_leader) values (otra, l.team_id, l.organization_id, false); rb := 'FALLO: pudo agregar a una persona a su equipo'; exception when insufficient_privilege then rb := 'OK: no pudo agregar a una persona a su equipo'; end; begin insert into public.team_member_positions (team_member_id, team_position_id) values (l.tm_id, pos); rc := 'FALLO: pudo agregar una posición'; exception when insufficient_privilege then rc := 'OK: no pudo agregar una posición'; when unique_violation then rc := 'FALLO: pasó la seguridad y chocó con una fila existente'; end; select count(*) into n from public.team_members where team_id = l.team_id; rd := case when n >= 1 then 'OK: sigue leyendo su equipo (' || n || ' filas)' else 'FALLO: ya no lee su equipo' end; reset role; set local role authenticated; perform set_config('request.jwt.claims', json_build_object('email', a.email, 'role', 'authenticated')::text, true); update public.team_members set is_leader = is_leader where id = l.tm_id; get diagnostics n = row_count; re := case when n = 1 then 'OK: el administrador sigue escribiendo' else 'FALLO: el administrador no pudo escribir' end; reset role; raise exception 'Resultado (se deshace todo): a) %; b) %; c) %; d) %; e) %', ra, rb, rc, rd, re; end $$;
